import{bQ as o,aL as c,u as d,G as a}from"./chunks/framework.DOL3HN83.js";const u=JSON.parse('{"title":"qy-workspace：旧 ERP 证据与迁移来源","description":"","frontmatter":{},"headers":[],"relativePath":"consumers/qy-workspace.md","filePath":"consumers/qy-workspace.md","lastUpdated":null}'),r={name:"consumers/qy-workspace.md"};function t(i,e,n,l,p,s){return c(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="qy-workspace-旧-erp-证据与迁移来源" tabindex="-1">qy-workspace：旧 ERP 证据与迁移来源 <a class="header-anchor" href="#qy-workspace-旧-erp-证据与迁移来源" aria-label="Permalink to &quot;qy-workspace：旧 ERP 证据与迁移来源&quot;">​</a></h1><h2 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to &quot;角色&quot;">​</a></h2><p><code>qy-workspace</code> 是旧 ERP 行为、调用频率和迁移差异的来源，不是 <code>qy-components</code> 的新架构、公共 interface、发布入口或版本权威。其根 <code>AGENTS.md</code> 明确该仓库包含业务子项目和私有 <code>@qiyin/*</code> 库，且许多引用必须按 Vite alias 与真实 import 解析。</p><h2 id="查证与验收入口" tabindex="-1">查证与验收入口 <a class="header-anchor" href="#查证与验收入口" aria-label="Permalink to &quot;查证与验收入口&quot;">​</a></h2><ul><li>工作区结构、ERP 命令与 alias 解释规则：消费者仓库的 <code>AGENTS.md</code>。</li><li>每个待迁移调用的真实解析：该项目及目标子项目的 <code>vite.config.ts</code>、<code>tsconfig</code>、源码 import 与调用链；不要从包名推断落点。</li><li>ERP 侧验证：按目标子项目现有命令执行；根规则列出的 ERP 入口为 <code>pnpm run dev --root=erp</code>、<code>pnpm run build --root=erp</code> 和项目测试。迁移验收仍须选择实际受影响页面。</li></ul><h2 id="可以作为来源的内容" tabindex="-1">可以作为来源的内容 <a class="header-anchor" href="#可以作为来源的内容" aria-label="Permalink to &quot;可以作为来源的内容&quot;">​</a></h2><p>旧组件的可观察行为、真实调用频率、字段/视觉兼容要求和未迁移缺口，可用来形成 Candidate 或校验新的 Qy interface。提取前先对照 <a href="./../migration/extraction-workflow">迁移流程</a> 和目标消费者，避免只从旧页面猜测公共边界。</p><h2 id="跨系统组件迁移盘点-2026-08-07" tabindex="-1">跨系统组件迁移盘点（2026-08-07） <a class="header-anchor" href="#跨系统组件迁移盘点-2026-08-07" aria-label="Permalink to &quot;跨系统组件迁移盘点（2026-08-07）&quot;">​</a></h2><p>本轮盘点同时覆盖 <code>packages/qiyin/components</code> 和各业务系统自己的 <code>packages/*/src/components</code>，排除 <code>node_modules</code>、<code>dist</code>、coverage 与 webpack 构建产物。候选优先级综合考虑跨系统重复、当前真实引用、已有 Qy 能力和业务耦合程度；目录中存在同名文件不等于已经证明应进入公共包。</p><p>重复证据包括：<code>SvgIcon</code> 在 11 个系统中存在相同实现，<code>IconSelect</code> 在 9 个系统中存在相同实现，<code>Screenfull</code> 在 8 个系统中存在相同实现；<code>FileUpload</code> 分布于 10 个系统；<code>Breadcrumb</code>、<code>SizeSelect</code>、<code>DictTag</code>、<code>RightToolbar</code>、<code>TreeSelect</code>、<code>ImagePreview</code>、<code>ImageUpload</code> 等旧后台组件在约 5 至 6 个系统重复。业务侧还存在 <code>SelectStaff</code>、<code>Category</code>、<code>Log</code>，以及 foundation、market、quotation、uni-app-market-quote 之间重复的 <code>SelectAttribute</code>、<code>FormCraft</code>、<code>FormProduct</code>。quotation 与 uni-app-market-quote 的成套报价组件属于业务模块复制，不按基础 UI 单组件处理。</p><p>基于这些来源形成的当前处理结果如下，不代表迁移或修改 qy-workspace 消费代码：</p><ol><li><code>QyIcon</code>、<code>QyIconPicker</code> 和 <code>QyFullscreen</code> 已由 <code>@qynpm/ui</code> 发布；消费者采用仍是独立任务。</li><li><code>QyDictTag</code>、<code>QyRichTextEditor</code>、<code>QyRichTextViewer</code>、<code>QyExcelPreview</code> 以及角色人员、属性、材质属性、工艺、基础产品和工序选择器已发布，尚未迁移消费者。</li><li>文件上传先比较旧 <code>FileUpload</code> 与现有 <code>QyUpload</code>、<code>QyFilePicker</code>、<code>QyImageUpload</code> 的差异，优先补兼容或迁移 adapter，不新建重叠上传实现。</li><li>业务选择器批次已经随 <code>@qynpm/pickers@0.0.4</code> 发布；工序属性等复合能力继续独立评估。业务 API、路由和新增表单仍由宿主或业务 adapter 注入。</li><li>富文本编辑/只读展示、电子表格预览与导入按各自依赖和业务策略规划独立能力包，不塞入基础 UI 根包。</li></ol><p>完整的已发布能力、功能缺口、候选顺序和多 renderer 未实现入口见 <a href="./../catalog/component-roadmap">公共组件现状与后续路线</a>。</p><p>已由现有公共能力覆盖的旧入口不再据此重复规划新组件：<code>SvgIcon</code> 对应 <code>QyIcon</code>，旧树选择、图片预览、图片上传、分页、表格、查询表单、弹窗和商品/店铺/普通人员选择分别核对现有 <code>@qynpm/ui</code>、<code>@qynpm/admin-patterns</code>、<code>@qynpm/table</code>、<code>@qynpm/form</code> 与 <code>@qynpm/pickers</code>。是否迁移任何消费者必须由对应项目另行立项，本清单不授权修改 qy-workspace。</p><p>旧 <code>Breadcrumb</code>、<code>HeaderSearch</code>、<code>Hamburger</code>、<code>TopNav</code>、<code>TagsView</code> 等后台框架壳整体映射到 <code>admin-shell</code> / <code>admin-framework</code>，不作为普通基础组件逐个重做。拼版 Canvas、三维包装预览、订单关联、业务日志和成套报价编辑器留在未来 qy-workspace 领域包或业务 adapter，不进入通用 UI 包。</p><h2 id="不得带入公共包的规则" tabindex="-1">不得带入公共包的规则 <a class="header-anchor" href="#不得带入公共包的规则" aria-label="Permalink to &quot;不得带入公共包的规则&quot;">​</a></h2><p>不得复制其目录结构、Vite alias、私有 <code>@qiyin/*</code> 源码引用、ERP 路由/状态、接口、payload 或临时补丁。旧行为证据不自动证明能力应被发布或已被新消费者采用。</p>',17)])])}const q=o(r,[["render",t]]);export{u as __pageData,q as default};
